/* Keep full names separate from portraits; reserve room above the scrollable tasks. */
main.screen[data-pet-page="11"] .title{left:18%;right:39%;top:3%;width:auto;max-width:none;font-size:clamp(16px,5cqw,22px);line-height:1.15;white-space:normal;overflow:visible;overflow-wrap:anywhere}
main.screen[data-pet-page="11"] .art-top{height:22.2%}
