main.screen[data-pet-page="11"] .couple{left:8%;right:38%;top:20.2%;display:grid;grid-template-columns:minmax(0,1fr) 12px minmax(0,1fr);gap:4px;margin:0;font-size:clamp(12px,3.4cqw,14.6px);line-height:1.15;text-align:center}
main.screen[data-pet-page="11"] .owner-name{min-width:0;white-space:normal;overflow-wrap:anywhere}
main.screen[data-pet-page="11"] .owner-separator{align-self:center}
main.screen[data-pet-page="11"] .tabs{top:29.5%;height:5%;min-height:44px}
main.screen[data-pet-page="11"] :is(.pet-task-list,.pet-weekly-panel){top:37%;bottom:12%}
</style>

