custom/m07-p25.html:
/* Full names wrap within the profile card rather than across portraits or actions. */
main.screen[data-pet-page="25"] .title{left:17%;right:17%;top:3.7%;width:auto;max-width:none;font-size:clamp(16px,5cqw,22px);line-height:1.1;white-space:normal;overflow:visible;overflow-wrap:anywhere;text-align:center}
main.screen[data-pet-page="25"] .dog{left:28%;top:24.5%;width:max-content;max-width:33%;transform:translateX(-50%);padding:2px 4px;border-radius:3px;background:#f8ead1e8;font-size:clamp(12px,3.4cqw,14px);line-height:1.15;white-space:normal;overflow-wrap:anywhere;text-align:center}
main.screen[data-pet-page="25"] .pet-owner-info{position:absolute;left:49%;right:6%;top:21%;display:flex;flex-direction:column;gap:3cqw;background:var(--prototype-paper-warm) url('../assets/book-v2/paper.webp') center/100% auto;border-radius:3px}
main.screen[data-pet-page="25"] .pet-owner-info :is(.couple,.day){position:static;inset:auto;width:auto;max-width:none;margin:0;white-space:normal;overflow-wrap:anywhere}
main.screen[data-pet-page="25"] .couple{display:grid;grid-template-columns:minmax(0,1fr) 12px minmax(0,1fr);gap:4px;font-size:clamp(12px,3.3cqw,14px);line-height:1.15;text-align:center}
main.screen[data-pet-page="25"] .owner-name{min-width:0;overflow-wrap:anywhere}
main.screen[data-pet-page="25"] .owner-separator{align-self:center}
main.screen[data-pet-page="25"] .day{font-size:clamp(11px,3cqw,13px);line-height:1.2}
</style>

